        </div>
      </div>

      {/* Streak Display */}
      {stats.streak && (stats.streak.current > 0 || stats.streak.longest > 0) && (
        <div className="p-4 border-t border-[#333] flex items-center justify-between">
          <div className="flex items-center gap-2">
