                    className="input-uber"
                    data-testid="profile-name"
                  />
                </div>
                <div>
                  <label className="block text-sm text-gray-400 mb-2">Role</label>
                  <select
                    value={formData.role}
                    onChange={(e) => setFormData({ ...formData, role: e.target.value })}
                    className="input-uber"
                    data-testid="profile-role"
                  >
