                {/* Phase 7: Community Details Section */}
                <div className="pt-4 border-t border-[#333]">
                  <h3 className="text-white font-medium mb-4 flex items-center gap-2">
                    <GraduationCap className="w-4 h-4 text-[#06C167]" />
